const now = new Date();
const day = now.getDay(); // 0 Sun ... 6 Sat
let back = 1;
if (day === 1) back = 3; // Monday -> report on Friday
if (day === 0) back = 2; // Sunday (manual run) -> report on Friday
const reportDate = new Date(now);
reportDate.setDate(now.getDate() - back);
const iso = reportDate.toISOString().slice(0, 10);
const label = reportDate.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
return [{ json: { reportDate: iso, reportDateLabel: label } }];

// Collapses department fan-out to exactly one item so downstream HTTP
// Request nodes run once, not once per department. $('Get Departments')
// still exposes the full list to later Code nodes regardless of this.
return [{ json: { ready: true } }];

const departments = $('Get Departments').all().map(i => i.json);
const deptById = new Map(departments.map(d => [d.id, d.name]));

return $input.all().map(item => {
  const e = item.json;
  return {
    json: {
      'Full Name': e.full_name,
      'Email': e.email,
      'Department': deptById.get(e.department_id) || 'Unknown',
      'Job Title': e.job_title,
      'Seniority': e.seniority,
      'Contract Type': e.contract_type,
      'Status': e.status,
      'Performance Score': e.performance_score,
    },
  };
});

const employees = $('Get Employees').all().map(i => i.json);
const departments = $('Get Departments').all().map(i => i.json);
const deptById = new Map(departments.map(d => [d.id, d.name]));
const empById = new Map(employees.map(e => [e.id, e]));
const reportDate = $('Compute Report Date').item.json.reportDate;

// 'alwaysOutputData' on Get Attendance means a day with zero attendance
// rows still delivers one placeholder item here (no employee_id) instead
// of being skipped entirely — filter it out before mapping real rows.
const rows = $input.all()
  .filter((item) => item.json && item.json.employee_id)
  .map((item) => {
    const a = item.json;
    const emp = empById.get(a.employee_id);
    return {
      json: {
        'Full Name': emp ? emp.full_name : 'Unknown',
        'Department': emp ? (deptById.get(emp.department_id) || 'Unknown') : 'Unknown',
        'Date': a.date,
        'Status': a.status,
        'Check In': a.check_in,
        'Check Out': a.check_out,
        'Hours Worked': a.hours_worked,
      },
    };
  });

// Keep at least one row so the XLSX/email steps downstream always run,
// even when the report date genuinely has no attendance data yet.
if (rows.length === 0) {
  return [{
    json: {
      'Full Name': '',
      'Department': '',
      'Date': reportDate,
      'Status': 'No attendance records for this date',
      'Check In': '',
      'Check Out': '',
      'Hours Worked': '',
    },
  }];
}
return rows;
